"""Starter question packs for software interviews: a few well-known questions
per subject, each with a model answer, so practice can start on day one.
Added from the Interview prep page; every question can be edited after.

Kept in English on purpose: technical interviews and their terms are."""

C, S, K, L = "choice", "short", "code", "long"
E, M, H = 1, 2, 3


def opts(right, *wrong):
    """Choices written right one first; they're shuffled when the pack is added (prep.install_pack)."""
    return [{"text": right, "correct": True}] + [{"text": w, "correct": False} for w in wrong]


